import{_ as u,a0 as l,w as i,s as d,I as t,x as s,a1 as n,A as e,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何在 Kubuntu 21.10 中升级 KDE Plasma 5.24 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kubuntu 21.10 中升级 KDE Plasma 5.24 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kubuntu 21.10 中升级 KDE Plasma 5.24 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kubuntu 21.10 中升级 KDE Plasma 5.24 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220212 How to Get KDE Plasma 5.24 in Kubuntu 21.10 Impish Indri","title":"如何在 Kubuntu 21.10 中升级 KDE Plasma 5.24","tag":"202202","desc":""},"relativePath":"202202/20220212 How to Get KDE Plasma 5.24 in Kubuntu 21.10 Impish Indri.md","filePath":"[post].md"}'),r={name:"202202/20220212 How to Get KDE Plasma 5.24 in Kubuntu 21.10 Impish Indri.md"};function b(m,a,k,h,g,K){const p=l("Link");return i(),d("div",null,[a[18]||(a[18]=t("h1",{id:"如何在-kubuntu-21-10-中升级-kde-plasma-5-24",tabindex:"-1"},[s("如何在 Kubuntu 21.10 中升级 KDE Plasma 5.24 "),t("a",{class:"header-anchor",href:"#如何在-kubuntu-21-10-中升级-kde-plasma-5-24","aria-label":"Permalink to “如何在 Kubuntu 21.10 中升级 KDE Plasma 5.24”"},"​")],-1)),a[19]||(a[19]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202202/17/093727qw3js653lzksscfw.jpg",alt:""})],-1)),a[20]||(a[20]=t("blockquote",null,[t("p",null,"KDE 开发人员启用了有名的 Backports PPA，以便你在 Kubuntu 21.10 中安装/升级到 KDE Plasma 5.24。 以下是方法。")],-1)),t("p",null,[a[1]||(a[1]=s("KDE Plasma 5.24 最近的 ",-1)),n(p,{href:"https://kde.org/announcements/plasma/5/5.24.0/"},{default:e(()=>[...a[0]||(a[0]=[s("发布",-1)])]),_:1}),a[2]||(a[2]=s(" 带来了令人兴奋的变化。在这个新版本中，你会得到一个全新的概览页面，它很像 GNOME 的概览。此外，还有崭新的默认 Breeze 主题、性能提升、通知外观的调整等。在我们的 [官方综述页面][2] 可以阅读更多关于这些功能的信息。",-1))]),a[21]||(a[21]=o(`<p>如果你很匆忙，没有时间阅读文章，这里有一组简短的命令，可以做到这些。😃</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt full-upgrade</span></span></code></pre></div><p>如果你运行 Kubuntu 21.10 Impish Indri，你不会马上得到这个更新。因为 Kubuntu 21.10 Impish Indri 目前采用 KDE Plasma 5.22.5 作为稳定版本。尽管 Kubuntu 21.10 计划在 2022 年 7 月结束生命，但你仍然可以通过 Backports PPA 安装 KDE Plasma 5.24。</p><p>然而，请注意，你将在 2022 年 4 月的 Kubuntu 22.04 LTS 中得到 KDE Plasma 5.24，这要比 Kubuntu 21.10 的寿命结束早得多。</p><h3 id="如何在-kubuntu-21-10-中安装-kde-plasma-5-24" tabindex="-1">如何在 Kubuntu 21.10 中安装 KDE Plasma 5.24 <a class="header-anchor" href="#如何在-kubuntu-21-10-中安装-kde-plasma-5-24" aria-label="Permalink to “如何在 Kubuntu 21.10 中安装 KDE Plasma 5.24”">​</a></h3><p>下面是你如何将 Kubuntu 21.10 中现有的 KDE Plasma 更新到最新版本。</p><h4 id="如何在-kubuntu-21-10-中安装-kde-plasma-5-24-1" tabindex="-1">如何在 Kubuntu 21.10 中安装 KDE Plasma 5.24 <a class="header-anchor" href="#如何在-kubuntu-21-10-中安装-kde-plasma-5-24-1" aria-label="Permalink to “如何在 Kubuntu 21.10 中安装 KDE Plasma 5.24”">​</a></h4><p>如果你习惯使用“<ruby>发现<rt>Discover</rt></ruby>” 感到满意，请添加 Backports PPA <code>ppa:kubuntu-ppa/backports</code> 作为软件源并点击更新。一旦检索到更新的软件包信息，就可以安装。</p><p>我建议使用以下终端方法，以获得更快和无错误的安装。</p><p>打开 Konsole，运行以下命令来添加 backports PPA。如果你喜欢，你可以验证你运行的 Plasma 是什么版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/02/Add-the-PPA.jpg" alt="Add the PPA"></p><p>现在，刷新软件包列表并验证最新的 5.24 软件包是否可供升级。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/02/Check-the-latest-KDE-Plasma-5.24-packages-before-upgrade.jpg" alt="Check the latest KDE Plasma 5.24 packages before upgrading"></p><p>现在运行最后的命令来启动升级。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt full-upgrade</span></span></code></pre></div><p>上面的命令会下载大约 270MB 以上的软件包。升级过程大约需要 10 分钟。命令完成后，重启你的系统。</p><p>而你应该通过 Kubuntu 21.10 Impish Indri 获得了全新的 KDE Plasma 5.24。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/02/KDE-Plasma-5.24-in-Kubuntu-21.10-1024x579.jpg" alt="KDE Plasma 5.24 in Kubuntu 21.10"></p><h4 id="如何在-ubuntu-21-10-中与-gnome-一起安装-kde-plasma-5-24" tabindex="-1">如何在 Ubuntu 21.10 中与 GNOME 一起安装 KDE Plasma 5.24 <a class="header-anchor" href="#如何在-ubuntu-21-10-中与-gnome-一起安装-kde-plasma-5-24" aria-label="Permalink to “如何在 Ubuntu 21.10 中与 GNOME 一起安装 KDE Plasma 5.24”">​</a></h4><p>如果你正在运行带有默认 GNOME 的 Ubuntu 21.10 Impish Indri，你也可以体验全新的 KDE Plasma 桌面，只需对上述命令稍作修改即可。</p><p>打开一个终端，依次运行下面的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backpots</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install kubuntu-desktop</span></span></code></pre></div><p>上述命令完成后，重启系统。在登录页面上，选择 KDE Plasma 作为桌面环境。然后你就可以开始了。</p><p>这将与 GNOME 桌面一起安装 KDE Plasma 5.24。</p><h4 id="我可以在-ubuntu-20-04-lts-中安装-kde-plasma-5-24-吗" tabindex="-1">我可以在 Ubuntu 20.04 LTS 中安装 KDE Plasma 5.24 吗？ <a class="header-anchor" href="#我可以在-ubuntu-20-04-lts-中安装-kde-plasma-5-24-吗" aria-label="Permalink to “我可以在 Ubuntu 20.04 LTS 中安装 KDE Plasma 5.24 吗？”">​</a></h4><p>Ubuntu 20.04 LTS 版有早期的 KDE Plasma 5.18、KDE Framework 5.68、KDE Applications 19.12.3。所以，在它的整个生命周期中，它不会收到最新的 KDE 更新。所以，从技术上讲，你可以添加上述 PPA 并安装 KDE Plasma 5.24。但我不建议这样做，因为不兼容的软件包框架可能会导致系统不稳定。</p><p>所以，建议你使用 Kubuntu 21.10 和上述的 Backports PPA 或者使用 KDE Neon 来体验最新的 Plasma 桌面。</p><h3 id="如何卸载" tabindex="-1">如何卸载 <a class="header-anchor" href="#如何卸载" aria-label="Permalink to “如何卸载”">​</a></h3><p>在任何时候，如果你想回到 KDE Plasma 桌面的原始版本，那么你可以安装 <code>ppa-purge</code> 并删除 PPA，接着刷新软件包。</p><p>打开一个终端，依次执行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ppa-purge</span></span>
<span class="line"><span>sudo ppa-purge ppa:kubuntu-ppa/backports</span></span>
<span class="line"><span>sudo apt update</span></span></code></pre></div><p>当命令完成，重启你的系统。</p><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to “结束语”">​</a></h3><p>我希望这个快速指南能让你从不同的使用情况下全面升级到 KDE Plasma 5.24。希望你能在没有任何错误的情况下完成升级。</p><p>请在下面的评论栏里告诉我进展如何。</p><hr>`,37)),t("p",null,[a[4]||(a[4]=s("via: ",-1)),n(p,{href:"https://www.debugpoint.com/2022/02/kde-plasma-5-24-kubuntu-21-10/"},{default:e(()=>[...a[3]||(a[3]=[s("https://www.debugpoint.com/2022/02/kde-plasma-5-24-kubuntu-21-10/",-1)])]),_:1})]),t("p",null,[a[9]||(a[9]=s("作者：",-1)),n(p,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...a[5]||(a[5]=[s("Arindam",-1)])]),_:1}),a[10]||(a[10]=s(" 选题：",-1)),n(p,{href:"https://github.com/lujun9972"},{default:e(()=>[...a[6]||(a[6]=[s("lujun9972",-1)])]),_:1}),a[11]||(a[11]=s(" 译者：",-1)),n(p,{href:"https://github.com/geekpi"},{default:e(()=>[...a[7]||(a[7]=[s("geekpi",-1)])]),_:1}),a[12]||(a[12]=s(" 校对：",-1)),n(p,{href:"https://github.com/wxy"},{default:e(()=>[...a[8]||(a[8]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[15]||(a[15]=s("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原创编译，",-1)),n(p,{href:"https://linux.cn/"},{default:e(()=>[...a[14]||(a[14]=[s("Linux中国",-1)])]),_:1}),a[17]||(a[17]=s(" 荣誉推出",-1))])])}const E=u(r,[["render",b]]);export{D as __pageData,E as default};
